  background: var(--panel);
  border: 1px solid var(--cyan);
  width: 100%;
  max-width: 480px;
  max-height: 96vh;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5), inset 0 0 15px color-mix(in srgb, var(--cyan) 10%, transparent);
  box-sizing: border-box;
}

.minesweeper-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid var(--line);
  padding-bottom: 6px;
}

.minesweeper-title {
  font-family: var(--display);
  font-size: 15px;
  color: var(--paper);
  margin: 0;
  letter-spacing: 0.05em;
}

.minesweeper-close-btn {
  background: transparent;
  border: 1px solid var(--line);
  color: var(--muted);
  width: 26px;
  height: 26px;
  font-size: 16px;
  cursor: pointer;
  display: grid;
  place-items: center;
  transition: all 0.2s ease;
}

.minesweeper-close-btn:hover {
  border-color: var(--cyan);
  color: var(--cyan);
}

.minesweeper-toolbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--ink);
  border: 1px solid var(--line);
  padding: 6px 12px;
}

.minesweeper-stat {
  font-family: var(--mono);
  font-size: 14px;
  color: var(--cyan);
  letter-spacing: 0.05em;
}

