  initSnakeGameEngine(overlay) {
    const canvas = overlay.querySelector("#snake-game-canvas");
    const ctx = canvas.getContext("2d");
    const scoreEl = overlay.querySelector("#snake-score");
    const hiEl = overlay.querySelector("#snake-hi");
    const grid = 32;
