permissionRequest.newFileContents:
.pong-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(9, 11, 10, 0.85);
  backdrop-filter: blur(8px);
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease;
}

.pong-modal-overlay.is-active {
  opacity: 1;
  pointer-events: auto;
}

.pong-modal-container {
  background: var(--surface);
  border: 1px solid var(--cyan);
  box-shadow: 0 0 30px rgba(145, 243, 168, 0.2);
  width: 100%;
  max-width: 520px;
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.85rem;
}

.pong-header {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid var(--line);
  padding-bottom: 0.65rem;
}

.pong-title {
  font-family: var(--font-mono);
  font-size: 0.95rem;
  color: var(--cyan);
  margin: 0;
  letter-spacing: 0.05em;
}

.pong-close-btn {
  background: none;
  border: 1px solid var(--line);
  color: var(--ink);
  width: 28px;
  height: 28px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-mono);
  font-size: 1.2rem;
  transition: all 0.2s;
}

.pong-close-btn:hover {
  background: var(--cyan);
  color: var(--ink);
  border-color: var(--cyan);
}

.pong-mode-selector {
  width: 100%;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.5rem;
}

.pong-mode-btn {
  background: var(--ink);
  border: 1px solid var(--line);
  color: var(--ink-muted);
  font-family: var(--font-mono);
  font-size: 0.75rem;
  padding: 0.45rem 0;
  cursor: pointer;
  transition: all 0.15s;
  text-transform: uppercase;
}

.pong-mode-btn.is-active {
  background: var(--cyan);
  color: var(--ink);
  border-color: var(--cyan);
  font-weight: 500;
}

.pong-diff-selector {
  width: 100%;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0.35rem;
  transition: opacity 0.2s ease;
}

.pong-diff-selector.is-hidden {
  display: none;
}

.pong-diff-btn {
  background: var(--ink);
  border: 1px solid var(--line);
  color: var(--ink-muted);
  font-family: var(--font-mono);
  font-size: 0.7rem;
  padding: 0.4rem 0;
  cursor: pointer;
  transition: all 0.15s;
  text-transform: uppercase;
}

.pong-diff-btn.is-active {
  background: var(--cyan);
  color: var(--ink);
  border-color: var(--cyan);
  font-weight: 500;
}

.pong-stats {
  width: 100%;
  display: flex;
  justify-content: space-between;
  font-family: var(--font-mono);
  font-size: 0.8rem;
  color: var(--ink);
  background: var(--ink);
  padding: 0.5rem 0.75rem;
  border: 1px solid var(--line);
}

.pong-game-canvas-wrap {
  border: 1px solid var(--cyan);
  box-shadow: 0 0 10px rgba(145, 243, 168, 0.1);
  background: #000;
  display: flex;
  justify-content: center;
  align-items: center;
}

.pong-canvas {
  display: block;
  image-rendering: pixelated;
}

.pong-controls-hint {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  color: var(--ink-muted);
  text-align: center;
  margin: 0;
  letter-spacing: 0.05em;
}

.pong-touch-pad {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.5rem;
  width: 100%;
}

.pong-touch-btn {
  background: var(--ink);
  border: 1px solid var(--line);
  color: var(--cyan);
  font-family: var(--font-mono);
  font-size: 0.85rem;
  padding: 0.6rem 0;
  cursor: pointer;
  transition: all 0.15s;
}

.pong-touch-btn:hover, .pong-touch-btn:active {
  background: var(--cyan);
  color: var(--ink);
  border-color: var(--cyan);
}

