    function checkCollision(mat, pos) {
      for (let r = 0; r < mat.length; r++) {
        for (let c = 0; c < mat[r].length; c++) {
          if (mat[r][c] !== 0) {
            let nx = pos.x + c;
            let ny = pos.y + r;
            if (nx < 0 || nx >= COLS || ny >= ROWS) return true;
            if (ny >= 0 && grid[ny][nx] !== 0) return true;
          }
        }
      }
      return false;
