        player.pos.x += offset;
        offset = -(offset + (offset > 0 ? 1 : -1));
        if (offset > player.matrix[0].length) {
          player.matrix = oldMat;
          player.pos.x = x;
          return;
        }
      }
    }

    function playerMove(dir) {
      player.pos.x += dir;
      if (checkCollision(player.matrix, player.pos)) {
        player.pos.x -= dir;
      }
    }

    function playerDrop() {
      player.pos.y++;
      if (checkCollision(player.matrix, player.pos)) {
        player.pos.y--;
        merge();
