        row.forEach((val, c) => {
          if (val !== 0) {
            ctx.fillStyle = COLORS[val];
            ctx.fillRect(c * BLOCK + 1, r * BLOCK + 1, BLOCK - 2, BLOCK - 2);
          }
        });
      });

