    function checkCollision(mat, pos) {
      for (let r = 0; r < mat.length; r++) {
        for (let c = 0; c < mat[r].length; c++) {
          if (mat[r][c] !== 0) {
            let nx = pos.x + c;
            let ny = pos.y + r;
