      if (!overlay.classList.contains("is-active")) return;
      if (!isPaused && !gameOver) {
        const delta = time - lastTime;
        lastTime = time;
        dropCounter += delta;
        if (dropCounter > dropInterval) {
          playerDrop();
        }
      } else {
        lastTime = time;
      }
      draw();
      requestAnimationFrame(update);
    }

