      else if (e.key === "ArrowRight") { playerMove(1); e.preventDefault(); }
      else if (e.key === "ArrowDown") { playerDrop(); e.preventDefault(); }
      else if (e.key === "ArrowUp" || e.key === "x") { playerRotate(); e.preventDefault(); }
