        bombsRange.min = 1;
        bombsRange.max = 80;
        let pct = Math.round((totalMines / totalCells) * 100);
        if (pct < 1) pct = 1;
        if (pct > 80) pct = 80;
        bombsRange.value = pct;
        bombsVal.textContent = `${pct}%`;
      }
    };

