      stopTimer();
      seconds = 0;
      timeEl.textContent = "⏱️ 000";
      gameOver = false;
      gameWon = false;
      firstClick = true;
      flagsCount = 0;
      faceBtn.textContent = "😊";
      minesEl.textContent = `💣 ${totalMines - flagsCount}`;

