      const vGrid = rotateSprite(sprites.body, rotTimes).map(row => row.split(''));
      const hGrid = rotateSprite(sprites.bodyHorizontal, rotTimes).map(row => row.split(''));
      const grid = Array.from({ length: 32 }, () => Array(32).fill('.'));
      for (let r = 0; r < 32; r++) {
        for (let c = 0; c < 32; c++) {
          if (mask[r][c] === '#') {
