    sprites.turnLeftRight = makeTurnLeft(1);
    sprites.turnLeftDown = makeTurnLeft(2);
    sprites.turnLeftLeft = makeTurnLeft(3);

    const drawSprite = (ctx, sprite, x, y, size, color, glowColor) => {
