  flex-direction: column;
  gap: 6px;
  background: var(--ink);
  border: 1px solid var(--line);
  padding: 8px 10px;
}

.ms-setting-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  font-family: var(--mono);
  font-size: 11px;
  color: var(--muted);
}

.ms-size-btns {
  display: flex;
  gap: 4px;
}

.ms-size-btn {
  background: var(--panel);
  border: 1px solid var(--line);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 10px;
  padding: 3px 6px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.ms-size-btn:hover,
.ms-size-btn.active {
