        ctx.fillStyle = "rgba(9, 11, 10, 0.75)";
        ctx.fillRect(0, 0, WIDTH, HEIGHT);
        ctx.fillStyle = "#91f3a8";
        ctx.font = "bold 16px monospace";
        ctx.textAlign = "center";
        ctx.fillText("PAUSED", WIDTH / 2, HEIGHT / 2);
      }
    }

    function loop() {
      update();
      draw();
      requestAnimationFrame(loop);
    }

    const handleKeyDown = (e) => {
      if (!overlay.classList.contains("is-active")) return;
      if (e.key === "w" || e.key === "W") {
        player1.dy = -6;
        e.preventDefault();
      } else if (e.key === "s" || e.key === "S") {
        player1.dy = 6;
        e.preventDefault();
      }

      if (gameMode === "2p") {
        if (e.key === "ArrowUp") {
          player2.dy = -6;
          e.preventDefault();
        } else if (e.key === "ArrowDown") {
          player2.dy = 6;
          e.preventDefault();
        }
      }

      if (e.key === " ") {
        isPaused = !isPaused;
        e.preventDefault();
      } else if (e.key === "Enter" && gameOver) {
        this.pongReset();
        e.preventDefault();
      }
    };

    const handleKeyUp = (e) => {
      if (e.key === "w" || e.key === "W" || e.key === "s" || e.key === "S") {
        player1.dy = 0;
      }
      if (gameMode === "2p") {
        if (e.key === "ArrowUp" || e.key === "ArrowDown") {
          player2.dy = 0;
        }
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    window.addEventListener("keyup", handleKeyUp);

    overlay.querySelectorAll(".pong-touch-btn").forEach(btn => {
      const act = btn.getAttribute("data-action");
      btn.addEventListener("mousedown", () => { player1.dy = act === "up" ? -6 : 6; });
      btn.addEventListener("mouseup", () => { player1.dy = 0; });
      btn.addEventListener("touchstart", (e) => { e.preventDefault(); player1.dy = act === "up" ? -6 : 6; });
      btn.addEventListener("touchend", () => { player1.dy = 0; });
    });

    this.pongReset();
    requestAnimationFrame(loop);
  }
});

