  background: var(--ink);
  position: relative;
  aspect-ratio: 1;
}

.snake-canvas {
  width: 100%;
  height: 100%;
  display: block;
}

.snake-controls-hint {
  font-family: var(--mono);
  font-size: 11px;
  color: var(--muted);
  text-align: center;
}

.snake-touch-pad {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  max-width: 200px;
  margin: 0 auto;
}

.snake-touch-btn {
  background: var(--ink);
  border: 1px solid var(--line);
  color: var(--green);
  font-family: var(--mono);
  font-size: 16px;
  padding: 12px 0;
  text-align: center;
  cursor: pointer;
  user-select: none;
}

.snake-touch-btn:active {
  background: var(--green-dim);
  color: var(--paper);
}

.snake-btn-up { grid-column: 2; }
.snake-btn-left { grid-column: 1; grid-row: 2; }
.snake-btn-down { grid-column: 2; grid-row: 2; }
.snake-btn-right { grid-column: 3; grid-row: 2; }

