  soundEnabled() {
    try {
      return localStorage.getItem("portfolio-sound") !== "off";
    } catch {
      return true;
    }
  },

  setSound(enabled) {
    try {
      localStorage.setItem("portfolio-sound", enabled ? "on" : "off");
