    const WIDTH = canvas.width;
    const HEIGHT = canvas.height;

    let gameMode = "vs_ai";
    let p1Score = 0;
    let p2Score = 0;
    let difficulty = "medium";

    const paddleWidth = 10;
    const paddleHeight = 60;
    const ballSize = 8;

    let player1 = {
