/* BIOS Boot Screen */
.bios-boot-screen {
  position: fixed;
  inset: 0;
  background: #000;
  color: #c0c0c0;
  font-family: var(--mono);
  font-size: 14px;
  line-height: 1.6;
  z-index: 99999;
  padding: 48px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  cursor: pointer;
  transition: opacity 0.5s ease, visibility 0.5s ease;
}
.bios-boot-screen.is-hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}
.bios-content {
  max-width: 800px;
}
.bios-line {
  margin: 0 0 4px 0;
  white-space: pre-wrap;
  opacity: 0;
  animation: biosFadeIn 0.1s forwards;
}
.bios-persistent {
  margin: 0 0 4px 0;
  white-space: pre-wrap;
  opacity: 1;
}
.bios-line:nth-child(1) { animation-delay: 0.1s; }
.bios-line:nth-child(2) { animation-delay: 0.25s; }
.bios-line:nth-child(3) { animation-delay: 0.4s; }
.bios-line:nth-child(4) { animation-delay: 0.55s; }
.bios-line:nth-child(5) { animation-delay: 0.7s; }
.bios-line:nth-child(6) { animation-delay: 0.85s; }
.bios-line:nth-child(7) { animation-delay: 1.05s; }
.bios-line:nth-child(8) { animation-delay: 1.25s; }
.bios-line:nth-child(9) { animation-delay: 1.45s; }
.bios-line:nth-child(10) { animation-delay: 1.65s; }
.bios-line:nth-child(11) { animation-delay: 1.85s; }
.bios-line:nth-child(12) { animation-delay: 2.1s; }
.bios-line:nth-child(13) { animation-delay: 2.35s; }
.bios-line:nth-child(14) { animation-delay: 2.6s; }
.bios-line:nth-child(15) { animation-delay: 2.85s; }
.bios-line:nth-child(16) { animation-delay: 3.1s; }
.bios-line:nth-child(17) { animation-delay: 3.35s; }
.bios-line:nth-child(18) { animation-delay: 3.6s; }
.bios-line:nth-child(19) { animation-delay: 3.9s; }
.bios-line:nth-child(20) { animation-delay: 4.2s; }
.bios-line:nth-child(21) { animation-delay: 4.5s; }
.bios-line:nth-child(22) { animation-delay: 4.8s; }
.bios-line:nth-child(23) { animation-delay: 5.2s; }
.bios-line:nth-child(24) { animation-delay: 5.6s; }
.bios-line:nth-child(25) { animation-delay: 6.0s; }
.bios-line:nth-child(26) { animation-delay: 6.4s; }

.bios-green {
  color: var(--green);
}
.bios-dim {
  color: var(--muted);
}
.bios-footer {
  display: flex;
  justify-content: space-between;
  color: #fff;
  background: #0000aa;
  padding: 6px 12px;
  font-size: 13px;
  font-weight: bold;
}
@keyframes biosFadeIn {
  to { opacity: 1; }
}
@media (max-height: 640px) {
  .menu-item.folder-tile .folder-icon { width: 19px; height: 13px; }
  .menu-item.folder-tile .folder-icon::before { top: -4px; width: 7px; height: 3px; }
  .folder-name { font-size: 9px; }
  .folder-meta { font-size: 6px; }
  .directory-heading { min-height: 24px; }
  .directory-hint { margin-top: 3px; font-size: 7px; }
}
@media (max-height: 560px) {
  .page-shell { min-height: 0; }
  .topbar { min-height: 68px; padding-top: 6px; padding-bottom: 3px; }
  .route-bar { order: 0; width: auto; margin: 0 0 0 auto; font-size: 7px; }
  .system-status { font-size: 7px; }
  .page-controls { min-height: 42px; }
  .home-screen.is-active { gap: 8px; }
  .menu-item.folder-tile { min-height: 50px; }
  .directory-heading { min-height: 21px; }
  .directory-hint { margin-top: 1px; }
}
@media (min-width: 761px) and (max-height: 760px) {
  #screen-about { padding-block: 24px; }
}
@media (min-width: 1300px) {
  .page-shell { width: 100%; max-width: 100%; padding: 0 48px; }
  .home-content { max-width: 1100px; }
  .intro { max-width: 880px; }
  .hero-rule, .home-menu { width: min(100%, 880px); }
  .project-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 20px; }
}

/* Interactive Elements Press + Spring Effect */
button,
a,
.menu-item,
.index-tile,
.folder-tile:not(.is-dragging),
.cv-link,
.contact-chip,
.send-button,
.project-row,
.topic-folder:not(.is-dragging),
.pager-button,
#page-dots button,
.theme-option,
.lang-option,
.terminal-btn {
  transition: transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275), background-color 0.18s ease, color 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
}

button:active,
a:active,
.menu-item:active,
.index-tile:active,
.folder-tile:not(.is-dragging):active,
.cv-link:active,
.contact-chip:active,
.send-button:active,
.project-row:active,
.topic-folder:not(.is-dragging):active,
.pager-button:active,
#page-dots button:active,
.theme-option:active,
.lang-option:active,
.terminal-btn:active {
  transform: scale(0.97);
}
  .skills-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 24px; }
}
@media (min-width: 1700px) {
  .page-shell { width: 100%; max-width: 100%; padding: 0 64px; }
  .home-content { max-width: 1300px; }
  .intro { max-width: 1020px; }
  .hero-rule, .home-menu { width: min(100%, 1020px); }
  .project-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 24px; }
}

@media (max-width: 768px) {
  .page-shell {
    width: 100%;
    height: 100vh;
    height: 100svh;
    border: none;
    padding: 0 16px;
  }
  .screen {
    padding: 20px 16px;
  }
  .home-screen.is-active {
    grid-template-columns: 1fr;
  }
  .about-contact-grid {
    grid-template-columns: 1fr;
    gap: 24px;
  }
}

